_CN_DIGITS = {"零": 0, "一": 1, "二": 2, "两": 2, "三": 3, "四": 4,
              "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}


def _cn_number(s):
    """中文数字 → int（支持 十/十五/二十/二十三/五 等常见形式）；解析失败返回 None。

    为什么需要它：旧版 step 3 的正则只吃阿拉伯数字 `\\d`，
    于是「近十天」解析失败 → 返回 -1 → 起始日期被算成「今天+1」→ OpenAlex 必然 0 命中
    （2026-10-05 实测）。中文数字在口语时间窗里很常见，必须与阿拉伯数字同等对待。
    """
    if not s:
        return None
    if s.isdigit():
        return int(s)
    if "十" in s:
        left, _, right = s.partition("十")
        if (left and left not in _CN_DIGITS) or (right and right not in _CN_DIGITS):
            return None
        tens = _CN_DIGITS[left] if left else 1     # 「十」= 10
        ones = _CN_DIGITS[right] if right else 0   # 「十五」= 15
        return tens * 10 + ones
    return _CN_DIGITS.get(s)


def parse_lookback(text=None):
    """把用户说法解析为回溯天数。

    支持：
      - 显式中文短语：近三天/近一周/近半个月/近一个月/近三个月/近半年/近一年…
      - "N天/N日"：如 "近45天"、"30天"
      - "N周"：如 "2周"
      - "N个月/N月"：如 "2个月"
      - "N年"：如 "2年"
      - 纯数字：视为天数
    -1 表示"未解析"，由调用方用默认值兜底。
    """
    if not text:
        return -1
    t = (text or "").strip()
    # 1) 精确短语表
    if t in TIME_PHRASES:
        return TIME_PHRASES[t]
    # 2) 去掉"近/约/大概"等前缀后查表
    import re as _re
    bare = _re.sub(r"^(近|整个|约|大概|最近)\s*", "", t)
    if bare in TIME_PHRASES:
        return TIME_PHRASES[bare]
    # 3~6) "X天/X日 / X周 / X个月 / X年"——数字位同时吃阿拉伯与中文数字
    #     （旧版只吃 \d，「近十天」整条落空，见 _cn_number docstring）
    _num = r"(\d{1,4}|[零一二两三四五六七八九十]{1,3})"
    for pat, mult in ((rf"近?\s*{_num}\s*[天日]", 1),
                      (rf"{_num}\s*周", 7),
                      (rf"{_num}\s*个?\s*月", 30),
                      (rf"{_num}\s*年", 365)):
        m = _re.search(pat, t)
        if m:
            n = _cn_number(m.group(1))
            if n is not None:
                return n * mult
    # 7) 纯数字天数
    if t.isdigit():
        return int(t)
    return -1


