def on_topic(title, abstract):
    """材料领域闸门（两段式，避免误杀）。

    判定顺序：
      1) 命中「强材料信号」→ 直接通过。
         强信号 = 材料门类词（alloy/perovskite/battery/catalyst…）或
                 计算材料学方法词（DFT/interatomic potential/band gap…）。
         ——这些词几乎不会出现在生医论文里，命中即可放心。
      2) 未命中强信号，但标题出现「非材料领域词」→ 淘汰。
      3) 其余（泛化学词如 molecule/synthesis，或干脆没词）→ 通过，
         交给 relevance() 的相关度阈值去卡；不在这里一刀切。
         ——第一版在这里一刀切，结果把 additive manufacturing、电池寿命预测、
           可解释 AI 等正当论文也误杀了，反而更糟。

    说明：AlphaFold 这类确实用 ML 做"结构预测"、常被当作 AI4S 代表，但它不是材料
    论文，本库不收；而"材料 + 生医交叉"（如生物材料、药物递送载体）只要命中材料
    门类词就保留，因为它们在材料侧有真实内容。
    """
    t = (title or "").lower()
    blob = f"{t} {abstract or ''}".lower()
    if any(k in blob for k in MATERIAL_STRONG):
        return True
    # 标题本身带材料/材料信息学词 → 保留（避免摘要里的生医词把正当论文误杀，
    # 例如 MatterGen「A generative model for inorganic materials design」）
    if _title_is_material(t):
        return True
    if any(k in t for k in OFFTOPIC_CORE):
        return False
    return True


def relevance(title, abstract, kw_tokens):
    """title+abstract 命中方向词的程度，0~1。

    方向词之间是 **OR** 语义（用户按 `A B C` 写法给的是同义/近义检索族，不是必须
    全部命中的词组）。若按「覆盖率 = 命中数/词数」打分，长查询（如
    `interpretable machine learning materials SHAP feature importance`，8 个词）
    几乎必然低于阈值而被全部滤掉——这正是旧版命中 0 篇的原因。

    改为「宽度 + 深度」双通道，取较大者：
      - 深度：单条最强命中（title 命中 0.9，仅摘要命中 0.7）
      - 宽度：分数按 max(4, 词数/2) 归一，即命中 ~4 个词就接近满分，
              超过 4 个额外命中以 0.1/词的边际递减奖励到上限 1.0

    命中判定走 `kw_hit`（整词边界），见该函数的注释。
    """
    if not kw_tokens:
        return 1.0
    t = (title or "").lower()
    a = (abstract or "").lower()
    hit_t = [k for k in kw_tokens if kw_hit(k, t)]
    hit_a = [k for k in kw_tokens if kw_hit(k, a) and k not in hit_t]
    if not hit_t and not hit_a:
        return 0.0

    depth = max([0.9] * len(hit_t) + [0.7] * len(hit_a))

    n_eff = len(hit_t) + len(hit_a)
    denom = max(4.0, len(kw_tokens) / 2.0)
    breadth = min(n_eff / denom, 1.0)
    breadth = min(breadth + 0.1 * max(0, n_eff - int(denom)), 1.0)

    return round(max(depth, breadth), 3)


def relevance_ok(rel, rel_min):
    """相关度是否过该刊阈值（纯函数，便于 selftest 不联网钉住分级语义）。

    🔴 **分级阈值当前对选择没有任何影响**（2026-10-10 用真实数据实测，非推测）：
    取当天 4 个方向的 **166 篇候选**统计 `relevance` 取值，只有 4 个值——
    0.70(66) ／ 0.769(2) ／ 0.900(94) ／ 0.923(4)；而 `SCORE_FLOOR = 0.70`。
    逐 tier 判定「会被滤掉几篇」：**T0 0 篇、T1 0 篇、T2 0 篇、T3 0 篇、T4 0 篇**；
    两两对比（T0 vs T4 等）判定不同的论文均为 **0 篇**。
    ⇒ 不是"几乎不产生区分"，而是**完全不产生区分**：五个档位行为完全相同。

    根因是结构性的：能走到这一步的候选**已经通过了关键词筛选**，其分数必然 ≥ 下限，
    而 0.40–0.70 的阈值全都 ≤ 下限 ⇒ 永远无物可滤。
    **未擅自下调 depth 权重**（那会改变真实召回，须先由上层拍板）；
    改为由 `inert_tiers()` 在每轮运行时**把这个事实报出来**，避免"分级在起作用"的错觉。
    """
    try:
        return float(rel) >= float(rel_min)
    except (TypeError, ValueError):
        return False


# `relevance()` 能给出的**最小正分值**（depth 通道：仅摘要命中 = 0.7；breadth 下限更低但
# 被 max() 抬到 depth 之上不会低于它——故 0.7 是正分值下限）。
# ⚠️ 若将来改 depth 权重（第 572 行的 0.9/0.7），**必须同步改这里**，否则 inert 判定会失真。
SCORE_FLOOR = 0.70


def inert_tiers(cfg, force_rel=None):
    """哪些档位的阈值**不可能滤掉任何候选**（阈值 ≤ 评分下限）→ 返回 [(tier, 阈值), ...]。

    判据：候选分数必然 ≥ `SCORE_FLOOR`（它们已过关键词筛选），故任何
    `relevance_min <= SCORE_FLOOR` 的阈值都无物可滤。这是**可自校准**的检查——
    若将来评分下限降到阈值以下，本函数自然返回空，无需有人记得来删警告。
    """
    out = []
    tiers = cfg.get("tiers") or {}
    for t in sorted(tiers):
        spec = tiers[t] if isinstance(tiers[t], dict) else {}
        try:
            th = float(force_rel if force_rel is not None
                       else spec.get("relevance_min", 0.0))
        except (TypeError, ValueError):
            continue
        if th <= SCORE_FLOOR:
            out.append((t, th))
    return out



def format_authors(work):
    """返回 (作者列表含通讯标注, 通讯作者串, 主要作者串)"""
    authorships = work.get("authorships") or []
    names = []
    corres = []
    orcid_by_name = {}
    for au in authorships:
        nm = (au.get("author") or {}).get("display_name") or ""
        if not nm:
            continue
        is_corr = au.get("is_corresponding") is True
        names.append(nm)
        if is_corr:
            corres.append(nm)
    # 主要作者 = 前 N 位（含首作者）
    main = names[:3] if names else []
    main_str = "、".join(main) if main else "[未提供]"
    # 🔴 通讯作者**取不到就留白**，绝不拿末位作者顶替。
    #    旧实现 `... or (names[-1] if names else "[未提供]")` **凭空造出通讯作者**：
    #    OpenAlex 的 authorships 经常整篇没有 is_corresponding 标记（尤其新上线论文），
    #    此时末位作者只是"排在最后的作者"，不是通讯作者。该值会一路流进候选 JSON、
    #    手动下载清单、卡片 frontmatter 和 lit_ingest ⇒ 与库内作者门禁
    #    「取不到就留白，不得凭领域印象补写」直接冲突。
    #    留空即可：卡片侧已有 `> ⚠️ 信息缺口` 标记承接这个空白。
    corres_str = "、".join(dict.fromkeys(corres)) if corres else ""
    return names, main_str, corres_str


def http_user_agent(cfg=None):
    """按配置构造 User-Agent：有 `datasource.mailto` 就带上（OpenAlex 礼貌池），
    没有就用**中性 UA**——**绝不编造邮箱**。

    🔴 为什么：`datasource.mailto` 现为空（占位地址比留空更糟：上游会把它当无效联系人，
    等于在请求里宣称一个不存在的联系人）。旧实现在这里写死
    `"lit-watch/1.0 (mailto:research)"`，与 lit_fetch 里的 `lit.watch@example.org`
    同属一类"假联系地址"。两处共用本函数 ⇒ 只改配置即可进礼貌池。
    """
    if cfg is None:
        try:
            cfg = K.load_lit_config()
        except Exception:                        # noqa: BLE001
            cfg = {}
    mail = str(((cfg.get("datasource") or {}).get("mailto") or "")).strip()
    base = "lit-watch/1.0 (literature discovery)"
    return f"{base} (mailto:{mail})" if mail else base


# 进程内全局请求节流（≈3 req/s）。OpenAlex 公共池上限 10 req/s，留足余量。
REQ_MIN_GAP = 0.34
_REQ_LOCK = threading.Lock()
_LAST_REQ = [0.0]


def _throttle():
    """请求之间的最小间隔。

    🔴 为什么需要它：分片改为线程池并发后（见 discover），若不加间隔就会**同时**打出 N 个
    请求——等于把原有的"温和节流"丢掉，反而更容易触发 429。节流放在 `_get` 内部，
    对每个请求（含重试）都生效，且**不增加请求数**。
    """
    with _REQ_LOCK:
        gap = REQ_MIN_GAP - (time.time() - _LAST_REQ[0])
        if gap > 0:
            time.sleep(gap)
        _LAST_REQ[0] = time.time()


def _get(url, timeout=30, retries=3, cfg=None):
    req = urllib.request.Request(url, headers={"User-Agent": http_user_agent(cfg)})
    for att in range(retries + 1):
        _throttle()
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            if att == retries:
                raise
            # 429 要指数退避（OpenAlex 限流），其它错误短等即可
            wait = (4 ** att) if e.code == 429 else 1.5
            print(f"[warn] HTTP {e.code}，{wait}s 后重试 ({att+1}/{retries})", file=sys.stderr)
            time.sleep(wait)
        except Exception:
            if att == retries:
                raise
            time.sleep(1.5)


def build_search_expr(query):
    """把方向关键词转成 OpenAlex search 表达式。

    旧版把整串原样传给 `search=`，OpenAlex 按「短语」匹配，结果几乎必然为 0 条，
    于是白名单期刊内的所有近期论文都被当成候选（含大量生物/医学噪声）。

    这里改为：按空格切词 → 转义 → 用 `AND` 连接。同义词族用 `~` 前缀显式分组，
    形如 `~a|b|c` 表示 (a OR b OR c)。只有全部组都命中才进候选，噪声大幅下降。
    """
    groups, cur = [], []
    for tok in (query or "").split():
        if tok.startswith("~"):
            if cur:
                groups.append(cur); cur = []
            cur = [tok[1:]]
        elif tok.endswith("~"):
            cur.append(tok[:-1])
            groups.append(cur); cur = []
        else:
            if cur:
                cur.append(tok)
            else:
                cur = [tok]
    if cur:
        groups.append(cur)
    parts = []
    for g in groups:
        g = [re.sub(r'[\\"()]', " ", w).strip() for w in g if w.strip()]
        g = [w for w in g if w]
        if not g:
            continue
        parts.append("(" + " OR ".join(f'"{w}"' for w in g) + ")" if len(g) > 1 else f'"{g[0]}"')
    return " AND ".join(parts)


def _date_key(d):
    """日期排序键：空日期归一为最小可比较键，保证与有效日期比较不炸且排最后。"""
    s = str(d or "").strip()
    return s if s else "0000"


def order_by_relevance(items):
    """相关度降序；同分时**新文献优先**（空日期排最后）。

    🔴 为什么不能写成一行 `key=(-relevance, date), reverse=True`：`reverse=True`
    会把 `-relevance` 再翻一次 ⇒ 相关度变成**升序**，`--limit` 截断时留下的正是
    相关度**最低**的几篇（2026-10-06 审计定位的严重缺陷）。
    这里用两次稳定排序实现「相关度降序 + 日期降序」：日期先按 desc 排好，
    再按相关度稳定排序，同分者的新文献次序得以保留。
    """
    items = sorted(items, key=lambda x: _date_key(x.get("publication_date")), reverse=True)
    return sorted(items, key=lambda x: -float(x.get("relevance") or 0.0))


def rank_and_truncate(out, config, limit):
    """排序 + 分级截断（纯函数，便于 selftest 不联网钉住规则）。

    截断规则（2026-10-06 分级）：T0/T1 为 uncapped（顶刊宁可多不能漏，全保留），
    其余按**相关度**填满到 limit；旧行为是无差别 `out[:limit]`，会用低档高产刊
    把顶刊挤掉。
    返回的展示顺序：先按档位（T0 在前），再相关度降序、新文献优先。
    """
    ranked = order_by_relevance(out)
    # 🔴 旧实现 `top = [...]; rest = [c for c in ranked if c not in top]`：
    #    ① `in` 对 dict 走 `==` 逐字段比较 ⇒ O(n²)；
    #    ② 更糟的是**内容相等即被剔除**——两篇标题/相关度/日期完全相同的候选
    #       （同源多刊、或跨刊转载）会整条从 rest 里消失，静默少给候选。
    #    改为单趟分区：按**对象身份**各归一处，每个候选恰好出现一次。
    spec_cache = {}
    top, rest = [], []
    for c in ranked:
        tier = c.get("journal_tier", "T3")
        spec = spec_cache.get(tier)
        if spec is None:
            spec = spec_cache[tier] = tier_spec(config, tier)
        (top if spec["uncapped"] else rest).append(c)
    rest = rest[:max(0, limit - len(top))]
    kept = order_by_relevance(top + rest)
    return sorted(kept, key=lambda x: tier_rank(x.get("journal_tier", "T3")))


def discover(query, config, days, limit, since_date=None, known=None):
    """检索 + 复筛。返回 (候选列表, 被跳过列表, 失败分片数, 截断信息 dict)。

    截断信息 dict: {"batches","per_page","max_pages","truncated_batches","raw"}，
    供 main 用**明确的计数**告警（旧实现超限静默丢，结果只是"看起来少了几篇"）。
    """
    api = config["datasource"]["api"]
    known = known or {}  # {去重键: 记录}，命中即视为已看过，跳过
    if since_date:  # 需求2：显式起始日期优先
        d = max(since_date, MIN_SINCE_DATE)
    else:
        days = min(days or 0, MAX_LOOKBACK_DAYS)
        d = datetime.date.today() - datetime.timedelta(days=days)
        d = max(d, MIN_SINCE_DATE)
    since = d.isoformat()
    days = (datetime.date.today() - d).days   # 回写实际生效天数，供报告/清单显示

    # 1) 解析期刊 source id
    sources = map_issn_to_source(config)
    # 2) 检索：期刊 + 日期窗口 + 有关键词匹配(优先在 title 层面)
    search_expr = build_search_expr(query)
    search_q = urllib.parse.quote(search_expr)
    # 后端已按 AND 词组精确检索，仍超量取回（per_page 上限 200）以便按相关度排序后取前 limit。
    per_page = min(max(limit * 5, 40), 200)

    # 🔴 OpenAlex 的 `source.id:A|B|...` OR 列表**上限 100 个 id**（实测 100 OK、101+ 报
    #    HTTP 400）。2026-10-06 白名单扩到 102 刊即越界——故按 90 个/批**分片检索后合并**。
    #    （90 留 10 个余量，防未来 OpenAlex 收紧或个别 id 形态异常。）
    src_ids = [s[0] for s in sources]  # s[0] 已经是纯 id 字符串
    if not src_ids:
        print("[warn] 未匹配到任何白名单期刊，将退化为仅按关键词检索", file=sys.stderr)
        batches = [[]]      # 无期刊过滤：单次检索
    else:
        CHUNK = 90
        batches = [src_ids[i:i + CHUNK] for i in range(0, len(src_ids), CHUNK)]

    # 🆕 每片最多翻几页（cursor 分页）。每页 per_page 条（≤200）⇒ 上限 3×200=600 条/片。
    #    为什么是 3：单片 90 刊、默认 7 天窗、再叠加 AND 关键词后，单片原始命中通常在
    #    数十条量级，3 页足够覆盖；同时把最坏情况的请求数锁定在 3 次/片（两片 ≈ 6 次），
    #    远低于公共池限额。
    MAX_PAGES = 3
    any_uncapped = any(tier_spec(config, t)["uncapped"]
                       for t in (config.get("tiers") or {}))
    # 每片的目标取回量：有 uncapped 档（T0/T1）时不可预知上限，放宽到翻页上限；
    # 否则按原 per_page 语义取够即停（只是允许翻页把它补齐）。
    target = per_page * (MAX_PAGES if any_uncapped else 1)

    def _fetch_shard(bi, batch):
        """取回一个分片（cursor 翻页）。返回 (works, truncated, err)。

        🔴 旧实现每片只发 **1 次** 请求、无 cursor 分页：超出 per_page 的命中被**静默丢弃**
        （T0/T1 是 uncapped，最吃亏——而那正是最不该漏的档）。
        现改为跟随 OpenAlex 的 `cursor=*`：翻到目标量或无下一页为止；若因翻页上限停下
        且仍有下一页，则把该片标记为**截断**并带上计数告警（绝不静默）。
        err 非 None = 该片有页失败（若已有部分命中则不丢，见下）。
        """
        if batch:
            src_filter = f",primary_location.source.id:{'|'.join(batch)}"
        else:
            src_filter = ""
        filters = f"from_publication_date:{since},type:article,has_abstract:true{src_filter}"
        base = (f"{api}/works?filter={urllib.parse.quote(filters)}"
                f"&search={search_q}&per_page={per_page}&sort=relevance_score:desc"
                f"&select=id,doi,title,publication_date,authorships,primary_location,"
                f"open_access,abstract_inverted_index")
        works, cursor, truncated, err = [], "*", False, None
        for _page in range(MAX_PAGES):
            # `*` 是"第一页"的字面量；后续 cursor 是 base64 串，必须原样编码
            cq = "*" if cursor == "*" else urllib.parse.quote(cursor, safe="")
            url = f"{base}&cursor={cq}"
            if len(batches) == 1 and _page == 0:
                print(f"检索 OpenAlex:\n  {url}\n", file=sys.stderr)
            try:
                data = _get(url, cfg=config)
            except Exception as e:                # noqa: BLE001
                # 🔴 旧版只 `continue`：整片白名单期刊的检索失败与「该片无命中」不可区分，
                #    最终被读成「该方向无新文献」——与 CLAUDE.md「计数器出错却被读成
                #    内容质量问题」同型。故计数并上抛给调用方。
                if not works:
                    raise
                err = e            # 已有部分命中：保留它们，但仍把这一片算作失败
                break
            works.extend(data.get("results") or [])
            cursor = ((data.get("meta") or {}).get("next_cursor")) or ""
            if not cursor:
                break
            if len(works) >= target:
                break
        # 🔴 循环结束时 `cursor` 仍非空 = **还有下一页但我们没取**（达到目标量或翻页上限）
        #    ⇒ 该片命中被截断，必须带上计数告警。只在循环内 `len>=target` 时置位是不够的：
        #    翻页上限先到时（命中稠密的片）同样丢了数据，那才是最该报的情况。
        if cursor:
            truncated = True
        return works, truncated, err

    results = []
    seen_ids = set()
    n_failed_batches = 0   # 失败分片计数：基础设施故障 ≠ 内容结论（见 main 里的告警/退出码 3）
    n_truncated_batches = 0
    raw_total = 0

    # 🆕 分片**并发**取回（2~4 线程）：旧实现顺序 fetch，两片就是两次串行往返。
    #    并发不改变请求数（每片最多 MAX_PAGES 次），间隔节流在 `_get` 内部统一施加。
    n_workers = max(1, min(4, len(batches)))
    if len(batches) > 1:
        print(f"[检索] 白名单 {len(src_ids)} 刊分 {len(batches)} 片，{n_workers} 线程并发"
              f"（每片最多翻 {MAX_PAGES} 页 × {per_page} 条）", file=sys.stderr)
    shard_works = {}
    with ThreadPoolExecutor(max_workers=n_workers) as ex:
        futs = [(bi, ex.submit(_fetch_shard, bi, b))
                for bi, b in enumerate(batches, 1)]
        # 按分片序号取回（future 早已并发在跑）⇒ 合并顺序与并发无关，结果可复现
        for bi, fut in futs:
            try:
                works, truncated, err = fut.result()
            except Exception as e:                # noqa: BLE001
                n_failed_batches += 1
                print(f"[warn] 分片 {bi} 检索失败（{e}），跳过该片", file=sys.stderr)
                continue
            if err is not None:
                n_failed_batches += 1
                print(f"[warn] 分片 {bi} 有页失败（{err}），仅合并已取回的 "
                      f"{len(works)} 条", file=sys.stderr)
            if truncated:
                n_truncated_batches += 1
                print(f"[warn] 分片 {bi} 达到翻页上限（{MAX_PAGES} 页 × {per_page} 条）"
                      f"但**仍有下一页** ⇒ 该片命中被截断，结果偏少", file=sys.stderr)
            shard_works[bi] = works

    for bi in sorted(shard_works):
        for w in shard_works[bi]:
            raw_total += 1
            wid = w.get("id")
            if wid and wid in seen_ids:           # 跨分片去重
                continue
            if wid:
                seen_ids.add(wid)
            results.append(w)
    print(f"命中 {len(results)} 篇(原始，{len(batches)} 片合并去重后)。"
          f"正在按关键词在 title+abstract 层面复筛…", file=sys.stderr)

    # 🆕 2026-10-10：把「分级阈值当前无物可滤」这件事**在运行时报出来**。
    #    实测（真实 166 篇候选）：分数只有 0.70/0.769/0.900/0.923 四种，全部 ≥ 评分下限
    #    ⇒ 五个档位的阈值一律 0 篇可滤，T0 与 T4 的判定完全相同。
    #    不报的话，读报告的人会以为 tier 正在做分级筛选。
    _inert = inert_tiers(config, force_rel=force_rel)
    if _inert:
        print(f"  [warn] 分级阈值**当前不产生任何区分**：{len(_inert)} 个档位的阈值 ≤ "
              f"评分下限 {SCORE_FLOOR}（{', '.join(f'{t}@{th:g}' for t, th in _inert)}）"
              f"⇒ 这些档位本轮不会滤除任何候选。"
              f"（根因：能走到复筛的候选必然已过关键词筛选，分数 ≥ 下限）",
              file=sys.stderr)

    kw = keyword_sets(query)
    issn_tier = _issn_tier_map(config)
    global_min = config["defaults"].get("abstract_min_relevance", 0.5)  # 兜底（tier_spec 已含）
    # 显式 --rel-min 覆盖时，对所有刊统一用该阈值（不再按档放宽）
    force_rel = config["defaults"].get("_force_rel_min", None)
    out = []
    skipped = []   # 命中去重账本、判定为"已看过"而被跳过的（供报告）
    seen_in_run = set()  # 单次 run 内按去重键再去重（同源多刊 / 检索回带重复）
    for w in results:
        title = (w.get("title") or "").strip()
        abs_ = reconstruct_abstract(w.get("abstract_inverted_index"))
        if not on_topic(title, abs_):
            continue
        src = ((w.get("primary_location") or {}).get("source") or {})
        issn = src.get("issn_l") or ""
        tier = issn_tier.get(issn, config.get("default_tier", "T3"))
        spec = tier_spec(config, tier)
        # 该刊的阈值：显式覆盖 > 档位阈值 > 全局兜底
        rel_min = force_rel if force_rel is not None else spec["relevance_min"]
        rel = relevance(title, abs_, kw)
        if not relevance_ok(rel, rel_min):
            continue
        names, main_str, corres = format_authors(w)
        cand = {
            "title": title,
            "main_authors": main_str,          # 主要作者（前3，含首作者）
            "authors_all": names,
            "corresponding_author": corres,    # 通讯作者
            "doi": (w.get("doi") or "").replace("https://doi.org/", ""),
            "journal": src.get("display_name") or "",
            "issn_l": issn,
            "journal_tier": tier,              # 🆕 分级标签
            "ingest_depth": spec["ingest_depth"],
            "publication_date": w.get("publication_date") or "",
            "relevance": rel,
            "oa_url": ((w.get("open_access") or {}).get("oa_url") or ""),
            "is_oa": ((w.get("open_access") or {}).get("is_oa")) or False,
            "abstract": abs_,
        }
        k = seen_key(cand)
        # 1) 已看过（历史账本命中）→ 跳过
        if k and k in known:
            skipped.append(cand)
            continue
        # 2) 本次 run 内重复 → 跳过
        if k and k in seen_in_run:
            continue
        if k:
            seen_in_run.add(k)
        out.append(cand)

    # 排序 + 分级截断（相关度降序、同分新文献优先；T0/T1 uncapped 全保留）
    out = rank_and_truncate(out, config, limit)
    trunc = {"batches": len(batches), "per_page": per_page, "max_pages": MAX_PAGES,
             "target": target, "truncated_batches": n_truncated_batches,
             "raw": raw_total}
    return out, skipped, n_failed_batches, trunc


def write_manifest(papers, path, query, days, since_label="", download_dir=""):
    """生成「可点开」的手动下载清单 md（阶段B 兜底用）。

    需求3：清单里的 DOI / PDF 直链用 markdown 链接，Obsidian 可直接点开；
    文件本身也给出可点开路径，由调用方在对话里把路径发成链接。

    ⚠️ 已知现状（2026-10-10 审计）：`daily/manifest_*.md` 目前**全库没有任何读取者**——
    `lit_digest`/`lit_fetch`/`lit_manual_import` 都不读它，阶段B 只按候选 JSON 下载。
    本函数保留该功能（它是人工兜底入口，人读即可），但**不要以为流水线会消费它**。
    """
    lines = []
    lines.append(f"# lit-watch 手动下载清单 · {query}")
    lines.append("")
    lines.append(f"> 生成日期：{datetime.date.today().isoformat()} ｜ "
                 f"时间窗：{since_label or f'近 {days} 天'}")
    lines.append("> 下列文献已通过阶段A锁定方向，但阶段B 自动/校园网直连未被程序化下载到")
    lines.append("> （付费墙或风控返回挑战页/403）。请按行在浏览器下载 PDF，放入：")
    lines.append(f"> `{download_dir}` ，然后回复「PDF已放好，继续入库」进入阶段C。")
    lines.append("")
    for i, p in enumerate(papers, 1):
        doi = p.get("doi") or ""
        name = p.get("journal") or ""
        lines.append(f"### {i}. {p['title']}")
        lines.append(f"- **期刊**：{name} [{p.get('journal_tier','')}]（{p.get('publication_date','')}）｜ 相关度 {p.get('relevance','')}")
        lines.append(f"- **主要作者**：{p.get('main_authors','—')}")
        lines.append(f"- **通讯作者**：{p.get('corresponding_author','—')}")
        if doi:
            lines.append(f"- **DOI**：[{doi}](https://doi.org/{doi})")
        if p.get("is_oa") and p.get("oa_url"):
            lines.append(f"- **OA 直链**：[点击下载]({p.get('oa_url')})")
        lines.append("")
    # 父目录不存在时直接写会 FileNotFoundError（--manifest 常指向尚未创建的批次目录）
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text("\n".join(lines), encoding="utf-8")
    return str(Path(path))


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    钉住去重链与时间窗解析——它们是本工具「不重复入库 / 不漏抓」的两处守门逻辑。
    去重键一旦错，同一篇会被反复入库（本库最忌讳的静默重复）。
    """
    ok = True

    # ---- normalize_title：大小写/标点/空白必须全部归一 ----
    cases = [
        ("Machine Learning for Materials", "machinelearningformaterials", "西文标题"),
        ("Machine-Learning,  for Materials!", "machinelearningformaterials",
         "标点与连字符须被去掉（跨写法等价）"),
        ("机器学习 材料 设计", "机器学习材料设计", "中文标题"),
        ("", None, "反例 空标题"),
    ]
    for src, want, label in cases:
        got = normalize_title(src)
        if want is None:
            print(f"  [{'ok' if got == '' else 'FAIL'}] {label} -> {got!r}")
            ok = ok and got == ""
        else:
            mark = "ok" if got == want else "FAIL"
            print(f"  [{mark}] {label}: {src[:28]!r} -> {got!r}")
            ok = ok and got == want
    # 跨写法等价是去重的核心前提
    same = (normalize_title("Machine-Learning for Materials")
            == normalize_title("machine learning for materials"))
    print(f"  [{'ok' if same else 'FAIL'}] 跨写法等价（去重前提）")
    ok = ok and same

    # ---- seen_key：优先 DOI，其次规范化标题；两者皆无返回 None ----
    got = seen_key({"doi": "10.1038/ABC.123.", "title": "X"})
    good = got == "doi:10.1038/abc.123"      # 小写 + 去尾点
    print(f"  [{'ok' if good else 'FAIL'}] seen_key 优先 DOI（小写+去尾点）-> {got!r}")
    ok = ok and good
    got = seen_key({"title": "Some Title"})
    print(f"  [{'ok' if got == 'title:sometitle' else 'FAIL'}] seen_key 回退标题 -> {got!r}")
    ok = ok and got == "title:sometitle"
    got = seen_key({})
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 无 DOI 无标题 -> {got!r}")
    ok = ok and got is None
    # 反例：空 DOI 串不得被当成有效 DOI
    got = seen_key({"doi": "  ", "title": "T"})
    print(f"  [{'ok' if got == 'title:t' else 'FAIL'}] 反例 空白 DOI 回退标题 -> {got!r}")
    ok = ok and got == "title:t"

    # ---- parse_lookback：中文短语 → 天数（正例）+ 未知短语（反例）----
    for phrase, want in (("近一周", 7), ("近半个月", 15), ("近一个月", 30),
                         # 回归夹具（2026-10-05 事故）：中文数字必须与阿拉伯数字等价，
                         # 否则「近十天」→ -1 → 起始日期=今天+1 → 0 命中（伪装成「无新文献」）
                         ("近十天", 10), ("近10天", 10), ("十天", 10),
                         ("近二十天", 20), ("近十五天", 15),
                         ("近三周", 21), ("近两个月", 60), ("近一年", 365)):
        try:
            got = parse_lookback(phrase)
        except Exception as e:                       # noqa: BLE001
            got = f"ERR:{e}"
        mark = "ok" if got == want else "FAIL"
        print(f"  [{mark}] parse_lookback {phrase} -> {got} (期望 {want})")
        ok = ok and got == want
    # 反例：确实无法解析的短语必须返回 -1（调用方据此回退，而非取负）
    for phrase in ("随便什么", "最近一段", ""):
        got = parse_lookback(phrase)
        mark = "ok" if got == -1 else "FAIL"
        print(f"  [{mark}] 反例 parse_lookback {phrase!r} -> {got} (期望 -1)")
        ok = ok and got == -1

    # ---- 相关度：整词边界（2026-10-10 回归夹具）----
    # 🔴 旧实现是子串匹配，两个已实测的假阳性：`oer` 命中 `coercion`/`coercive`，
    #    `dft` 命中任意含该三连字符的长串 ⇒ 相关度虚高、第二道复筛失效。
    #    这两条**必须判为不命中**（反例），同时正例不得被误杀。
    hit_cases = [
        (["oer"], "Coercive-field effects and coercion in ferroelectrics", False,
         "反例 oer 不得命中 coercion/coercive"),
        (["dft"], "A PDFT-based coarse-grained polymer model", False,
         "反例 dft 不得命中 PDFT（词内巧合）"),
        (["oer"], "OER activity of NiFe layered hydroxide", True, "正例 独立词 oer"),
        (["dft"], "DFT study of the zinc anode interface", True, "正例 独立词 dft"),
        (["dft"], "a dft-based high-throughput workflow", True, "正例 dft 后接连字符"),
        (["solid-state"], "solid state electrolyte design", True,
         "正例 连字符/空白等价"),
        (["machine learning"], "machine-learning potentials for alloys", True,
         "正例 多词短语跨连字符"),
    ]
    for kws, title, want, label in hit_cases:
        got = relevance(title, "", kws) > 0
        print(f"  [{'ok' if got == want else 'FAIL'}] {label} -> {got}")
        ok = ok and got == want
    # 反例：无命中必须给 0.0（而非虚高的"宽度分"）
    got = relevance("Solid oxide fuel cells", "", ["perovskite", "halide"])
    print(f"  [{'ok' if got == 0.0 else 'FAIL'}] 反例 完全无命中 -> {got}")
    ok = ok and got == 0.0
    # 正例：无关键词时按"全通过"处理（调用方已锁定方向）
    got = relevance("anything", "", [])
    print(f"  [{'ok' if got == 1.0 else 'FAIL'}] 正例 空关键词集 -> {got}")
    ok = ok and got == 1.0
    # ~ 词组必须展开成单词（否则 `~a|b|c` 永远匹配不到，相关度恒 0）
    ks = keyword_sets("battery ~lithium|sodium|zinc anode")
    good = "lithium" in ks and "sodium" in ks and "zinc" in ks and "~lithium|sodium|zinc" not in ks
    print(f"  [{'ok' if good else 'FAIL'}] OR 词组展开 -> {ks}")
    ok = ok and good

    # ---- 期刊分级：tier → 阈值/精读档（回归夹具，2026-10-06）----
    # 🔴 夹具用**合成配置**，不读真实 lit_config.yaml：旧版断言 `Nature=T0` / `0927-0256=T4`
    #    / T0=enhanced / T4=light 的**实况内容**，于是编辑白名单（本库每天都在做的事）
    #    就会让自检 FAIL —— 自检守的是代码逻辑，不是当前配置内容。
    #    （`lit_digest`/`lit_ingest` 本轮已同样改为环境无关夹具。）
    cfg = {
        "journals": [{"issn_l": "1111-1111", "name": "TopJournal", "tier": "T0"},
                     {"issn_l": "4444-4444", "name": "LowJournal", "tier": "T4"},
                     {"issn_l": "9999-0000", "name": "NoTierJournal"}],
        "tiers": {
            "T0": {"label": "正刊", "relevance_min": 0.40,
                   "ingest_depth": "enhanced", "uncapped": True},
            "T1": {"label": "子刊", "relevance_min": 0.45,
                   "ingest_depth": "enhanced", "uncapped": True},
            "T2": {"label": "一区", "relevance_min": 0.55, "ingest_depth": "standard"},
            "T3": {"label": "普通一区", "relevance_min": 0.60, "ingest_depth": "standard"},
            "T4": {"label": "二区", "relevance_min": 0.70, "ingest_depth": "light"},
        },
        "default_tier": "T3",
        "defaults": {"lookback_days": 7, "max_candidates": 20,
                     "abstract_min_relevance": 0.6},
        "datasource": {"api": "https://api.openalex.org", "mailto": ""},
    }
    spec0 = tier_spec(cfg, "T0")
    spec4 = tier_spec(cfg, "T4")
    good = spec0["relevance_min"] < spec4["relevance_min"]
    print(f"  [{'ok' if good else 'FAIL'}] 分级阈值单调（T0 {spec0['relevance_min']} < "
          f"T4 {spec4['relevance_min']}）")
    ok = ok and good
    good = spec0["uncapped"] and not spec4["uncapped"]
    print(f"  [{'ok' if good else 'FAIL'}] T0 uncapped / T4 不 uncapped")
    ok = ok and good
    good = spec0["ingest_depth"] == "enhanced" and spec4["ingest_depth"] == "light"
    print(f"  [{'ok' if good else 'FAIL'}] 精读档 T0=enhanced / T4=light")
    ok = ok and good
    # 缺 tiers 段时阈值必须回退到 defaults.abstract_min_relevance（不是 0.5 的硬编码）
    bare = tier_spec({"defaults": {"abstract_min_relevance": 0.62}}, "T9")
    good = bare["relevance_min"] == 0.62 and bare["ingest_depth"] == "standard"
    print(f"  [{'ok' if good else 'FAIL'}] 反例 缺 tiers 段回退 defaults -> "
          f"{bare['relevance_min']} / {bare['ingest_depth']}")
    ok = ok and good
    # issn→tier 映射：白名单里的刊映射到自己的档；未知刊回退默认档
    it = _issn_tier_map(cfg)
    good = (it.get("1111-1111") == "T0" and it.get("4444-4444") == "T4"
            and it.get("9999-0000") == "T3")
    print(f"  [{'ok' if good else 'FAIL'}] issn→tier 映射（含缺 tier 回退）-> {it}")
    ok = ok and good
    good = it.get("9999-9999", cfg.get("default_tier")) == cfg.get("default_tier")
    print(f"  [{'ok' if good else 'FAIL'}] 反例 未知 issn 回退默认档 "
          f"（{cfg.get('default_tier')}）")
    ok = ok and good
    # ---- 端到端分级闸门：同一个"弱命中"分，T0 留、T4 滤 ----
    # 直接用固定的相关度分（0.50）过各档阈值，钉住的是**分级语义**本身；
    # 不用 relevance() 现算，因为它的正值下限是 0.70（见 relevance_ok 的注释）。
    weak = 0.50
    good = (relevance_ok(weak, tier_spec(cfg, "T0")["relevance_min"])
            and not relevance_ok(weak, tier_spec(cfg, "T4")["relevance_min"]))
    print(f"  [{'ok' if good else 'FAIL'}] 弱命中 rel=0.50：T0 存活 / T4 被滤"
          f"（**纯函数语义**；注意真实候选拿不到 0.50 这么低的分数）")
    ok = ok and good
    good = relevance_ok(0.70, 0.70) and not relevance_ok(0.6999, 0.70)
    print(f"  [{'ok' if good else 'FAIL'}] 阈值边界：等于阈值算过、略低算不过")
    ok = ok and good

    # ---- 🆕 2026-10-10：inert_tiers —— 把"阈值无物可滤"变成可判定的断言 ----
    # 实测事实：真实候选分数下限 SCORE_FLOOR=0.70，而全部五档阈值都 ≤ 0.70
    # ⇒ 五档一律无物可滤，T0 与 T4 行为完全相同。这条夹具钉住该判定，
    # 一旦将来下调 depth 权重（下限跌破阈值），断言会 FAIL，提醒"分级开始起作用了、去更新文档"。
    inert = dict(inert_tiers(cfg))
    good = set(inert) == {"T0", "T1", "T2", "T3", "T4"}
    print(f"  [{'ok' if good else 'FAIL'}] inert_tiers 认定五档当前均无物可滤 -> {inert}")
    ok = ok and good
    good = SCORE_FLOOR == 0.70
    print(f"  [{'ok' if good else 'FAIL'}] SCORE_FLOOR 与 relevance() 的 depth 下限一致"
          f"（若改了 depth 权重必须同步改它）")
    ok = ok and good
    # 反例：把阈值设到下限之上，就不再是 inert（证明这判定真的会区分，不是恒真）
    fake = {"tiers": {"X": {"relevance_min": 0.8}, "Y": {"relevance_min": 0.7}}}
    fi = dict(inert_tiers(fake))
    good = (fi == {"Y": 0.7})
    print(f"  [{'ok' if good else 'FAIL'}] 反例：阈值 0.8 不算 inert、0.7（=下限）算 -> {fi}")
    ok = ok and good

    # ---- 排序 + 分级截断（2026-10-06 回归夹具）----
    # 🔴 排序符号写反时 `--limit` 截断保留的是**相关度最低**的几篇；
    #    这条断言不联网即可钉住「保留相关度最高的 N 篇」。
    cands = [
        {"title": "low",  "relevance": 0.60, "publication_date": "2026-09-01",
         "journal_tier": "T3"},
        {"title": "high", "relevance": 0.95, "publication_date": "2026-09-01",
         "journal_tier": "T3"},
        {"title": "mid",  "relevance": 0.75, "publication_date": "2026-09-01",
         "journal_tier": "T3"},
    ]
    kept = rank_and_truncate([dict(c) for c in cands], cfg, 2)
    titles = sorted(c["title"] for c in kept)
    good = titles == ["high", "mid"]
    print(f"  [{'ok' if good else 'FAIL'}] limit=2 保留相关度最高的两篇 -> {titles}")
    ok = ok and good
    good = [c["title"] for c in kept] == ["high", "mid"]      # 降序
    print(f"  [{'ok' if good else 'FAIL'}] 结果按相关度降序 -> {[c['title'] for c in kept]}")
    ok = ok and good
    # 同分时新文献优先；空日期不得让排序抛异常（且排最后）
    ties = [
        {"title": "old", "relevance": 0.80, "publication_date": "2025-01-01",
         "journal_tier": "T3"},
        {"title": "new", "relevance": 0.80, "publication_date": "2026-09-01",
         "journal_tier": "T3"},
        {"title": "nodate", "relevance": 0.80, "publication_date": "",
         "journal_tier": "T3"},
    ]
    try:
        kept2 = rank_and_truncate([dict(c) for c in ties], cfg, 3)
        got_order = [c["title"] for c in kept2]
        good = got_order == ["new", "old", "nodate"]
    except Exception as e:                        # noqa: BLE001
        got_order, good = f"ERR:{e}", False
    print(f"  [{'ok' if good else 'FAIL'}] 同分新文献优先、空日期排最后 -> {got_order}")
    ok = ok and good
    # 反例：T0 是 uncapped，limit 再小也必须全保留
    t0 = [{"title": f"t0_{i}", "relevance": 0.5 + i / 100, "publication_date": "2026-09-01",
           "journal_tier": "T0"} for i in range(3)]
    kept3 = rank_and_truncate(t0, cfg, 1)
    good = len(kept3) == 3
    print(f"  [{'ok' if good else 'FAIL'}] T0 uncapped：limit=1 仍保留全部 3 篇 -> {len(kept3)}")
    ok = ok and good

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="lit-watch 阶段A 发现")
    ap.add_argument("query", nargs="?", default="",
                    help="方向关键词，空格分隔(OR)，如 'zinc battery zn anode'")
    ap.add_argument("timewindow", nargs="?", default="",
                    help="时间窗中文短语（可选第2位置参数），如 近一周/近半个月/近一个月")
    ap.add_argument("--days", type=int, default=None,
                    help="回溯天数（数字），如 7 / 30")
    ap.add_argument("--since", default="",
                    help="时间窗中文短语或ISO日期，如 '近一周'/'近半个月'/'近一个月'/'2026-06-01'。"
                         "优先级高于 --days（需求2）。")
    ap.add_argument("--limit", type=int, default=None)
    ap.add_argument("--out", default="")
    ap.add_argument("--config", default=K.LIT_CONFIG_PATH,
                    help="lit 配置（默认 tools/lit_config.yaml）")
    ap.add_argument("--manifest", default="",
                    help="把下载清单额外写成可点开的 md（阶段B 兜底，含 DOI/直链）")
    ap.add_argument("--no-seen", action="store_true",
                    help="忽略本地文献目录去重（用于核查某方向本地已有哪些文献）")
    ap.add_argument("--rel-min", type=float, default=None,
                    help="覆盖 abstract_min_relevance（0~1），放宽/收紧方向复筛")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    # 注：`query` 原先为位置必填，会让 --selftest 无法单独运行，故改为此处校验
    if not args.query:
        ap.error("必须提供 query（方向关键词）")

    # 第2位置参数 timewindow 并入 since（方便 `/lit-watch xxx 近半个月` 这种写法）
    if args.timewindow and not args.since:
        args.since = args.timewindow

    cfg = load_config(args.config)
    if args.rel_min is not None:
        # 显式覆盖：对所有刊统一用该阈值（不按档放宽），故存入私有键供 discover 识别
        cfg["defaults"]["abstract_min_relevance"] = args.rel_min
        cfg["defaults"]["_force_rel_min"] = args.rel_min

    # 需求2：时间窗由用户消息决定（中文短语 或 显式日期）
    days = None
    since_date = None
    if args.since:
        s = args.since.strip()
        try:
            # 若是 ISO 日期，转成"从该日起回溯到今天"的天数
            d = datetime.date.fromisoformat(s)
            since_date = d
            days = (datetime.date.today() - d).days
        except ValueError:
            days = parse_lookback(s)  # 中文短语
            # 🔴 -1 = 未解析。若放任它流到 discover()，起始日期会被算成「今天+1」，
            #   OpenAlex 必然 0 命中——**错误表现为「该方向无新文献」而非报错**，
            #   与 CLAUDE.md「计数器本身出错却被读成内容质量问题」同型。
            #   故此处回退到 --days / 默认值，并显式告警；绝不静默取负。
            if days is None or days < 0:
                print(f"[warn] 时间窗 '{s}' 未能解析为天数，回退到 "
                      f"--days/defaults（实际 {args.days or cfg['defaults'].get('lookback_days', 7)} 天）",
                      file=sys.stderr)
                days = None
    if days is None:
        days = args.days or cfg["defaults"].get("lookback_days", 7)
    limit = args.limit or cfg["defaults"].get("max_candidates", 20)

    papers = []   # 新文献（未命中历史账本）
    skipped_all = []  # 已看过被跳过的，供报告
    raw_dir = (cfg.get("paths") or {}).get("raw_dir", "") or ""
    known = {} if args.no_seen else load_seen(raw_dir, cfg)

    papers, skipped_all, n_failed_batches, trunc = discover(
        args.query, cfg, days, limit, since_date=since_date, known=known)

    # 🔴 分片失败绝不能被读成「无新文献」：基础设施故障 ≠ 内容结论。
    if n_failed_batches:
        print(f"\n[!] ⚠️ 检索未完成：{n_failed_batches} 个分片失败，白名单未全覆盖；"
              f"本结果**不可**解读为该方向无新文献（请重跑）。", file=sys.stderr)
    # 截断是另一类"结果偏少"：不是故障，但必须让读结果的人看见计数，
    # 否则"少了 30 篇"与"本来就只有这些"完全无法区分。
    if trunc.get("truncated_batches"):
        print(f"\n[!] ⚠️ 有 {trunc['truncated_batches']}/{trunc['batches']} 个分片达到翻页上限"
              f"（每片 {trunc['max_pages']} 页 × {trunc['per_page']} 条，仍有下一页）"
              f"⇒ 这几片的命中被截断，本结果**偏少**；可缩小时间窗或收紧 --rel-min 后重跑。",
              file=sys.stderr)

    if skipped_all:
        print(f"\n已跳过 {len(skipped_all)} 篇本地已有 / 库内已建卡 / 本 run 重复的文献：")
        for p in skipped_all:
            print(f"  - {p['title']}  [{p.get('journal') or ''}]  DOI: {p.get('doi') or '—'}")
        print(f"  去重源: {(cfg['paths'].get('catalogue')) if cfg else '—'}")
        print(f"          {(cfg['paths'].get('doi_index')) if cfg else '—'}"
              f"\n  （新入库文献重跑 tools/lit_catalogue.py 与 tools/kb_dois.py 即会被纳入去重）")

    # 注：不去重账本回写——catalogue 由 lit_catalogue.py 维护，
    # 只读用于去重。新下载文献入库后重跑同步即可覆盖后续去重。
    if not papers:
        if skipped_all:
            print("本次时间窗口+期刊+方向内没有新的未收录文献（全部命中本地目录）。")
        else:
            print("未发现符合条件的新文献（该时间窗口+期刊+方向内无命中）。")
    else:
        print("\n===== 发现结果（新文献） =====")
        for i, p in enumerate(papers, 1):
            print(f"\n[{i}] {p['title']}")
            tier = p.get("journal_tier", "")
            print(f"    期刊: {p['journal']}  [{tier}]  |  发表日期: {p['publication_date']}  |  相关度: {p['relevance']}")
            print(f"    主要作者: {p['main_authors']}")
            print(f"    通讯作者: {p['corresponding_author']}")
            print(f"    DOI: {p['doi']}")
            if p["is_oa"] and p["oa_url"]:
                print(f"    OA: {p['oa_url']}")
            else:
                print(f"    OA: 非开放获取（需手动下载）")

        if args.out:
            # 父目录不存在时 open() 会 FileNotFoundError（--out 常指向尚未创建的批次目录）
            Path(args.out).parent.mkdir(parents=True, exist_ok=True)
            with open(args.out, "w", encoding="utf-8") as f:
                json.dump({"query": args.query, "days": days,
                           "generated": datetime.date.today().isoformat(),
                           # 取回侧的诊断（供上层判断"结果是否完整"）
                           "retrieval": {"batches": trunc.get("batches"),
                                         "failed_batches": n_failed_batches,
                                         "truncated_batches": trunc.get("truncated_batches"),
                                         "per_page": trunc.get("per_page"),
                                         "max_pages": trunc.get("max_pages"),
                                         "raw_hits": trunc.get("raw")},
                           "papers": papers},
                          f, ensure_ascii=False, indent=2)
            print(f"\n候选清单已写入: {args.out}")

        if args.manifest:
            # 清单里的"把 PDF 放这里"必须是**真收件箱**（lit_manual_import 的 DEFAULT_INBOX
            # = <pdf_dir>/Manual Download）。旧代码这里传的是 paths.download_dir，
            # 而该键按配置注释是"被墙件**清单**的落点"，不是 PDF 收件箱 ⇒ 指引是错的。
            dl_dir = os.path.join(cfg["paths"].get("pdf_dir") or "raw/pdf", "Manual Download")
            since_label = args.since or f"近 {days} 天"
            mp = write_manifest(papers, args.manifest, args.query, days,
                                since_label=since_label, download_dir=dl_dir)
            print(f"\n下载清单(可点开)已写入: {mp}")

    # 🔴 退出码：只要有分片失败就返回 3（**两个分支都要**）。
    #    旧实现只在「papers 为空」分支里 exit(3)；一旦找到任何一篇就落到 exit 0 ——
    #    而那恰恰是更常见的情况（分片 1 成功 + 分片 2 失败）⇒ SKILL.md / runbook.md /
    #    _LIT-WATCH-NEXT.md 一致承诺的 `3 = 有分片失败` 在真实场景里**从未生效**，
    #    lit_daily 的 `partial` 判定因此也永远是 False。
    if n_failed_batches:
        print(f"[!] 因 {n_failed_batches} 个分片检索失败，退出码 3"
              f"（请重跑，勿据此判断无新文献）。", file=sys.stderr)
        sys.exit(3)
    sys.exit(0)


if __name__ == "__main__":
    # 🔴 必须 `sys.exit(main())`：旧写法直接调用 main() 会**丢掉返回值** ⇒
    #    `--selftest` 即使 FAIL 也以退出码 0 结束，kb_toolcheck 的"实跑"判据读不出来。
    sys.exit(main())
